import type { BuildState, ProducerRef, TypeRef } from "@hypit/hypit/protocol";
import type { StudioTemporalBinding, StudioTemporalProjection, StudioTemporalRelationCompanion } from "@hypit/studio-companion";
export type IdentifyTemporalSource = (type: TypeRef, value: unknown) => {
    readonly companion: string;
    readonly id: string;
    readonly kind: string;
    readonly itemId: string;
} | undefined;
export type FindTemporalRelation = (producer: ProducerRef, output: string) => StudioTemporalRelationCompanion | undefined;
/** Read one exact executed Temporal record through package-owned relation semantics. */
export declare function executedTemporalProjection(state: BuildState, record: string, identify?: IdentifyTemporalSource, relationFor?: FindTemporalRelation): StudioTemporalProjection | undefined;
/**
 * Read Temporal lineage from one executed output closure. Studio follows graph
 * identity; packages explain relation meaning through their Companions.
 */
export declare function executedTemporalBindings(state: BuildState, output: string, identify?: IdentifyTemporalSource, relationFor?: FindTemporalRelation): readonly StudioTemporalBinding[];
